<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>北辰新闻网 — 首页</title>
<meta name="description" content="北辰新闻网提供国内、财经、科技等领域的新闻报道与深度观察。">
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:"PingFang SC","Microsoft YaHei","Hiragino Sans GB","Heiti SC",sans-serif;color:#222;background:#f4f4f4;line-height:1.7;font-size:15px}
a{color:#222;text-decoration:none}
a:hover{color:#c0261f}
img,svg{display:block}
.wrap{max-width:1100px;margin:0 auto;padding:0 16px}
.top{background:#fafafa;border-bottom:1px solid #e7e7e7}
.topbar{display:flex;justify-content:space-between;align-items:center;height:36px;font-size:12px;color:#8a8a8a;flex-wrap:wrap}
.topbar a{color:#8a8a8a;margin-left:14px}
.masthead{display:flex;align-items:center;gap:16px;padding:20px 16px;flex-wrap:wrap}
.logo{display:flex;align-items:center;gap:12px}
.logo-name{font-size:30px;font-weight:700;letter-spacing:3px;color:#c0261f;line-height:1.2}
.logo-sub{font-size:12px;color:#aaa;letter-spacing:4px}
.search{margin-left:auto;display:flex;border:1px solid #ddd;background:#fff}
.search input{border:0;padding:9px 12px;width:200px;outline:none;font-size:13px;font-family:inherit}
.search button{border:0;background:#c0261f;color:#fff;padding:0 20px;font-size:13px;cursor:pointer;font-family:inherit}
.mainnav{background:#c0261f;box-shadow:0 2px 4px rgba(0,0,0,.08)}
.mainnav .wrap{display:flex;flex-wrap:wrap;padding:0 16px}
.mainnav a{color:#fff;padding:12px 22px;font-size:16px}
.mainnav a:hover,.mainnav a.on{background:#9c1b16;color:#fff}
.bulletin{background:#fff;border-bottom:1px solid #eee;font-size:13px;color:#666;padding:8px 0}
.bulletin b{color:#c0261f;margin-right:8px}
.layout{display:grid;grid-template-columns:1fr 320px;gap:24px;margin:20px auto;max-width:1100px;padding:0 16px}
.card{background:#fff;border:1px solid #e9e9e9;margin-bottom:20px}
.card-hd{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #eee;padding:12px 16px}
.card-hd h2{font-size:18px;border-left:4px solid #c0261f;padding-left:10px;line-height:1.3}
.card-hd span a{font-size:12px;color:#999}
.card-bd{padding:16px}
.lead{text-align:center;padding:22px 16px 18px;border-bottom:1px solid #eee}
.lead h1{font-size:30px;line-height:1.4;font-weight:700}
.lead h1 a:hover{color:#c0261f}
.lead p{color:#777;font-size:14px;margin-top:10px;text-align:left}
.lead .sub{margin-top:12px;font-size:14px;color:#555}
.lead .sub a{margin:0 10px}
.feature{display:grid;grid-template-columns:300px 1fr;gap:18px;padding:16px;border-bottom:1px solid #f0f0f0}
.feature:last-child{border-bottom:0}
.feature h3{font-size:20px;margin-bottom:8px}
.feature p{color:#777;font-size:14px}
.meta-s{font-size:12px;color:#aaa;margin-top:10px}
.meta-s em{font-style:normal;color:#c0261f;margin-right:10px}
.thumb{width:100%;height:170px;border:1px solid #eee}
.news-list{list-style:none}
.news-list li{padding:10px 0;border-bottom:1px dashed #ececec;display:flex;gap:12px;align-items:baseline}
.news-list li:last-child{border-bottom:0}
.news-list li a{flex:1;font-size:16px}
.news-list li a::before{content:"·";color:#c0261f;margin-right:8px;font-weight:700}
.news-list time{font-size:12px;color:#bbb;white-space:nowrap}
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}
.rank{list-style:none;counter-reset:r}
.rank li{counter-increment:r;padding:9px 0;border-bottom:1px dashed #ececec;display:flex;gap:10px}
.rank li:last-child{border-bottom:0}
.rank li::before{content:counter(r);background:#ddd;color:#fff;width:20px;height:20px;border-radius:2px;font-size:12px;text-align:center;line-height:20px;flex:none;margin-top:3px}
.rank li:nth-child(-n+3)::before{background:#c0261f}
.tags a{display:inline-block;border:1px solid #e0e0e0;color:#666;font-size:13px;padding:4px 10px;margin:0 8px 8px 0;background:#fcfcfc}
.tags a:hover{border-color:#c0261f;color:#c0261f}
.weather{display:flex;align-items:center;gap:14px}
.weather .t{font-size:34px;color:#c0261f;font-weight:700}
.weather small{display:block;color:#999;font-size:12px}
.pics{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.pics figcaption{font-size:14px;padding:8px 2px;text-align:center}
footer{background:#2b2b2b;color:#9b9b9b;margin-top:26px;padding:28px 0 20px;font-size:13px}
footer a{color:#9b9b9b}
footer a:hover{color:#fff}
.fcols{display:flex;flex-wrap:wrap;gap:40px;padding-bottom:18px;border-bottom:1px solid #3c3c3c}
.fcols h4{color:#ddd;font-size:14px;margin-bottom:8px}
.fcols ul{list-style:none}
.copy{padding-top:16px;line-height:2;color:#7d7d7d}
@media(max-width:880px){.layout{grid-template-columns:1fr}.feature{grid-template-columns:1fr}.two-col{grid-template-columns:1fr}.search{display:none}}
</style>
</head>
