            <g fill="#8f9fd0"><rect x="56" y="52" width="78" height="8"/><rect x="56" y="70" width="60" height="8"/><rect x="56" y="88" width="70" height="8"/><rect x="56" y="106" width="44" height="8"/></g>
            <circle cx="214" cy="74" r="34" fill="none" stroke="#c0261f" stroke-width="4"/>
            <path d="M238 98 L268 128" stroke="#c0261f" stroke-width="8" stroke-linecap="round"/>
          </svg>
          <figcaption><a href="keji.html">走进重点实验室：一块芯片的三百次测试</a></figcaption>
